const customers = await api.get("/customers", {});
const mails = await api.get("/mails", {});
const delayed = customers.items.filter(c => c.order && c.order.status === "delayed");
const delayedIds = new Set(delayed.map(c => c.id));
const complaints = mails.items.filter(m => m.label === "complaint");
const matches = complaints.filter(m => m.customer_id && delayedIds.has(m.customer_id)).map(m => ({ mail_id: m.id, customer_id: m.customer_id, from: m.from_email, subject: m.subject }));
return { delayed: delayed.map(c => ({ id: c.id, name: c.name, order: c.order.order_id })), complaintMails: complaints.map(m => ({ id: m.id, customer_id: m.customer_id, from: m.from_email, contact_id: m.contact_id })), matches };
